using Vibe.Registry;
using Vibe.Registry.Remote;

namespace Vde.SysMan;

// SYSMAN: serves HKLM\System, a Windows-shaped state of the machine generated by plugins from /etc, /proc, /sys,
// /dev and udev's database. Refilled when the files and udev's database change, and every minute. Served with
// fhived's protocol so each client is held to the permissions in the hive; everything here is readable by all and
// changeable by nobody.
public sealed class SystemService : IDisposable
{
    public const string DefaultSocketPath = "/run/sysman/system.sock";

    private readonly GeneratedHiveService _service;
    private readonly IReadOnlyList<ISystemPlugin> _plugins;
    private readonly string _root;

    public SystemService(IEnumerable<ISystemPlugin>? plugins = null, string root = "/", Func<System.Net.Sockets.Socket, RegistryIdentity>? identityOf = null, TimeSpan? periodic = null)
    {
        _plugins = (plugins ?? SystemBuilder.DefaultPlugins).ToList();
        _root = root;
        _service = new GeneratedHiveService("System", hive => SystemBuilder.Fill(hive, _plugins, _root), identityOf, periodic ?? TimeSpan.FromMinutes(1));
    }

    public Hive Hive => _service.Hive;
    public HiveServer Server => _service.Server;
    public void Refresh() => _service.Refresh();

    public void Watch()
    {
        _service.Watch(_plugins.SelectMany(p => p.WatchedFiles(_root)));
        _service.WatchDirectories(_plugins.SelectMany(p => p.WatchedDirectories(_root)));
    }

    public void Dispose() => _service.Dispose();
}
